import { ref, nextTick } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import DockerNetworks from "@/components/Network/DockerNetworks.vue"; // 引入子组件

export default {
  __name: 'DeleteNetworkDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const network = ref([]);
    const networksRef = ref(null); // 用于访问 DockerNetworks 组件

    const openDialog = async () => {
      network.value.name = '';
      dialogVisible.value = true;
      await nextTick();
      networksRef.value?.fetchNetworks();
    };
    const submitDelete = async () => {
      if (!network.value.name) {
        ElMessage.warning('请选择网络名称');
        return;
      }
      try {
        await axios.delete(`http://localhost:8081/network/delete/${network.value.name}`);
        ElMessage.success('删除成功');
        await networksRef.value.fetchNetworks(); // 更新子组件的网络数据
        network.value.name = '';
      } catch (err) {
        ElMessage.error('删除失败');
      }
    };

    // 向父组件暴露方法
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      network,
      networksRef,
      openDialog,
      submitDelete,
      ref,
      nextTick,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerNetworks
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
